if ! [[ "$date" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "bad date: $date (expected YYYY-MM-DD)" >&2; exit 2; fi
mon=$((10#${date:5:2})) day=$((10#${date:8:2}))
[ "$mon" -ge 1 ] && [ "$mon" -le 12 ] && [ "$day" -ge 1 ] && [ "$day" -le 31 ] || { echo "bad date: $date (expected YYYY-MM-DD)" >&2; exit 2; }

